perl -MTime::HiRes=time -e '
sub run_cap {
  my ($prog,$arg)=@_;
  my $pid = open(my $fh, "-|");
  die unless defined $pid;
  if ($pid==0){ open(STDERR,">","/dev/null"); exec($prog,$arg); exit 127; }
  local $/; my $out=<$fh>; close($fh);
  my $code = $? >> 8;
  return ($out//"", $code);
}
my $t=time();
for (1..500){ run_cap("/workspace/dataset/test16_executable","abc"); run_cap("/output/test16","abc"); }
printf "1000 runs: %.2fs\n", time()-$t;
my ($o,$c)=run_cap("/output/test16","http://x/y"); print "out=[$o] code=$c\n";
'

