perl -e '
use strict; use warnings;
sub run_cap {
  my ($prog,$arg)=@_;
  my $pid = open(my $fh, "-|");
  die "fork failed" unless defined $pid;
  if ($pid==0){ open(STDERR,">","/dev/null"); exec($prog,$arg); exit 127; }
  local $/; binmode($fh); my $out=<$fh>; close($fh);
  my $code = $? >> 8;
  return ($out//"", $code);
}
sub repr {
  my ($s)=@_;
  $s =~ s/\\/\\\\/g; $s =~ s/\x27/\\\x27/g;
  $s =~ s/([^\x20-\x7E])/sprintf("\\x%02X",ord($1))/ge;
  return "\x27$s\x27";
}
srand(20260810);
# weighted alphabet: specials heavy, digits, letters, space, multibyte tokens
my @heavy = (":")x8, ("/")x8, ("@")x6, ("?")x6, ("#")x6, ("[")x4, ("]")x4,
            ("%")x6, (".")x6, ("-")x5, ("+")x5, (" ")x4;
my @digits = ("0".."9"); push @heavy, @digits, @digits, @digits;
my @letters = ("a".."z","A".."Z"); push @heavy, @letters, @letters;
my @mb = ("\xc3\xa9", "\xe4\xbe\x8b"); # é, 例
my @ascii = map { chr($_) } (0x20..0x7E);

my @inputs;
for (1..50000) {
  my $len = int(rand(41)); # 0..40
  my $s = "";
  for (1..$len) {
    my $r = rand();
    if ($r < 0.06) { $s .= $mb[int(rand(scalar @mb))]; }
    else { $s .= $heavy[int(rand(scalar @heavy))]; }
  }
  push @inputs, $s;
}
for (1..5000) {
  my $len = int(rand(41));
  my $s = "";
  $s .= $ascii[int(rand(scalar @ascii))] for (1..$len);
  push @inputs, $s;
}

my $n=0; my @mm;
for my $s (@inputs) {
  my ($o1,$c1) = run_cap("/workspace/dataset/test16_executable", $s);
  my ($o2,$c2) = run_cap("/output/test16", $s);
  $n++;
  if ($o1 ne $o2 || $c1 != $c2) {
    push @mm, "INPUT: ".repr($s)."\n  REF: code=$c1 out=".repr($o1)."\n  GOT: code=$c2 out=".repr($o2);
  }
}
print "tested=$n mismatches=".scalar(@mm)."\n";
print "$_\n" for @mm;
'

